1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	const PROCESSING_FEE = 5;
13	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
14	
15	const BASE_PREMIUMS: Record<string, number> = {
16	  sword: 100,
17	  amulet: 60,
18	  staff: 80,
19	  potion: 40,
20	  rune: 25,
21	  moonstone: 25,
22	};
23	
24	const COMPONENT_PREMIUM = 25;
25	const BLOCK_SIZE = 3;
26	const BLOCK_PREMIUM = 60;
27	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
28	
29	const basePremium = (item: Item): number => BASE_PREMIUMS[item.type] ?? 0;
30	
31	const componentGroupPremium = (count: number): number =>
32	  count === BLOCK_SIZE ? BLOCK_PREMIUM : count * COMPONENT_PREMIUM;
33	
34	const applyFirstInsuranceSurcharge = (amount: number): number =>
35	  (amount * (100 + FIRST_INSURANCE_SURCHARGE_PERCENT)) / 100;
36	
37	const roundInMhpcoFavor = (premium: number): number => Math.ceil(premium);
38	
39	const isComponent = (item: Item): boolean => COMPONENT_TYPES.has(item.type);
40	
41	const isMainItem = (item: Item): boolean => !isComponent(item);
42	
43	const countByType = (components: Item[]): Map<string, number> => {
44	  const counts = new Map<string, number>();
45	  for (const component of components) {
46	    counts.set(component.type, (counts.get(component.type) ?? 0) + 1);
47	  }
48	  return counts;
49	};
50	
51	const componentsTotalByType = (components: Item[]): number =>
52	  [...countByType(components).values()].reduce(
53	    (total, count) => total + componentGroupPremium(count),
54	    0,
55	  );
56	
57	const itemsBasePremium = (items: Item[]): number => {
58	  const components = items.filter(isComponent);
59	  const mainItems = items.filter(isMainItem);
60	  const mainItemsTotal = mainItems.reduce(
61	    (sum, item) => sum + basePremium(item),
62	    0,
63	  );
64	  return mainItemsTotal + componentsTotalByType(components);
65	};
66	
67	const CURSE_SURCHARGE_PERCENT = 50;
68	
69	const itemSurcharges = (items: Item[]): number =>
70	  items.reduce(
71	    (sum, item) =>
72	      sum + (item.cursed ? (basePremium(item) * CURSE_SURCHARGE_PERCENT) / 100 : 0),
73	    0,
74	  );
75	
76	export const quote = (
77	  customer: Customer,
78	  items: Item[],
79	  contractIndex: number,
80	): number => {
81	  const base = itemsBasePremium(items);
82	  const total =
83	    applyFirstInsuranceSurcharge(base) + itemSurcharges(items) + PROCESSING_FEE;
84	  return roundInMhpcoFavor(total);
85	};
86	
87	export const claim = (): number => {
88	  return undefined as unknown as number;
89	};
